public class Main {
    public static void main(String[] args) {
        Account a = new Account("Ana", 50);
        Account b = new Account("Ben", 10);
        a.deposit(25);
        boolean ok = b.withdraw(30);
        System.out.println(a.owner + ": " + a.balance);
        System.out.println(b.owner + ": " + b.balance + " (withdraw ok? " + ok + ")");
    }
}

class Account {
    String owner;
    int balance;

    Account(String owner, int balance) {
        this.owner = owner;
        this.balance = balance;
    }

    void deposit(int amount) {
        balance += amount;
    }

    boolean withdraw(int amount) {
        if (amount > balance) {
            return false;
        }
        balance -= amount;
        return true;
    }
}
